import java.util.List;
import java.util.concurrent.ConcurrentLinkedDeque;

import org.springframework.stereotype.Service;

/**
 * Keeps every message sent through the contact form for as long as the application runs.
 */
@Service
public class ContactMessageService {

    private final ConcurrentLinkedDeque<ContactMessage> messages = new ConcurrentLinkedDeque<>();

    public void save(ContactMessage message) {
        messages.addFirst(message);
    }

    /**
     * @return all sent messages, newest first
     */
    public List<ContactMessage> findAll() {
        return List.copyOf(messages);
    }
}
