+package com.example.contact;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+
+import java.util.UUID;
+import java.util.regex.Pattern;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.context.SpringBootTest.WebEnvironment;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.options.AriaRole;
+
+@SpringBootTest(webEnvironment = WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Override
+    public String getView() {
+        return "/contact";
+    }
+
+    @Test
+    void sendButtonSendsTheMessageAndDisablesItself() {
+        String name = "Browser " + UUID.randomUUID();
+        fieldByLabel("Name").fill(name);
+        fieldByLabel("Phone").fill("0401 234 567");
+        fieldByLabel("Message").fill("Hello from the browser");
+
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send")).click();
+
+        assertThat(page.getByText("Message sent")).isVisible();
+        assertThat(page.getByText(name)).isVisible();
+        assertThat(fieldByLabel("Name")).hasValue("");
+        assertThat(page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send"))).isDisabled();
+    }
+
+    @Test
+    void enterInTheMessageFieldSendsTheMessage() {
+        String name = "Enter " + UUID.randomUUID();
+        fieldByLabel("Name").fill(name);
+        fieldByLabel("Phone").fill("0401 234 567");
+        fieldByLabel("Message").fill("Sent with Enter");
+
+        fieldByLabel("Message").press("Enter");
+
+        assertThat(page.getByText("Message sent")).isVisible();
+        assertThat(page.getByText(name)).isVisible();
+    }
+
+    @Test
+    void enterWhileTheLeaveDialogIsOpenDoesNotSend() {
+        fieldByLabel("Name").fill("Modal " + UUID.randomUUID());
+        fieldByLabel("Phone").fill("0401 234 567");
+        fieldByLabel("Message").fill("Should not be sent");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+        assertThat(dialogButton("Discard")).isVisible();
+        page.keyboard().press("Enter");
+        page.waitForTimeout(1000);
+
+        assertThat(page.getByText("Message sent")).not().isVisible();
+        assertThat(dialogButton("Discard")).isVisible();
+    }
+
+    @Test
+    void emptyFormShowsTheValidationMessages() {
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send")).click();
+
+        assertThat(page.getByText("Name is required")).isVisible();
+        assertThat(page.getByText("Give an e-mail address or a phone number")).isVisible();
+        assertThat(page.getByText("Message is required")).isVisible();
+        assertThat(page.getByText("Message sent")).not().isVisible();
+    }
+
+    @Test
+    void aboutLinkAsksBeforeLeavingWithTypedInput() {
+        fieldByLabel("Name").fill("Keeper");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+
+        assertThat(dialogButton("Keep editing")).isVisible();
+        dialogButton("Keep editing").click();
+        assertThat(dialogButton("Keep editing")).isHidden();
+        assertThat(fieldByLabel("Name")).hasValue("Keeper");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+        assertThat(dialogButton("Discard")).isVisible();
+        dialogButton("Discard").click();
+
+        assertThat(page).hasURL(Pattern.compile(".*/about$"));
+        assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About"))).isVisible();
+    }
+
+    @Test
+    void aboutLinkWithAnEmptyFormLeavesStraightAway() {
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+
+        assertThat(page).hasURL(Pattern.compile(".*/about$"));
+        assertThat(dialogButton("Discard")).isHidden();
+    }
+
+    private Locator fieldByLabel(String label) {
+        return page.getByLabel(label, new Page.GetByLabelOptions().setExact(true));
+    }
+
+    // The vaadin-dialog host element has no size of its own, so its visibility is checked via a button inside it
+    private Locator dialogButton(String text) {
+        return page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName(text));
+    }
+}
