+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.UUID;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.example.about.AboutView;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private static final String LONG_MESSAGE = "x".repeat(501);
+
+    @Test
+    void formHasTheExpectedFieldsAndAnEnabledSendButton() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", find(H1.class).single().getText());
+        assertEquals("About", find(RouterLink.class).single().getText());
+        assertEquals("", nameField().getValue());
+        assertEquals("", emailField().getValue());
+        assertEquals("", phoneField().getValue());
+        assertEquals("", messageField().getValue());
+        assertTrue(sendButton().isEnabled());
+        assertTrue(find(Grid.class).exists());
+    }
+
+    @Test
+    void emptyFormMarksTheRequiredFieldsAndSendsNothing() {
+        navigate(ContactView.class);
+        int rows = rowCount();
+
+        test(sendButton()).click();
+
+        assertTrue(nameField().isInvalid());
+        assertEquals("Name is required", nameField().getErrorMessage());
+        assertTrue(emailField().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", emailField().getErrorMessage());
+        assertTrue(messageField().isInvalid());
+        assertEquals("Message is required", messageField().getErrorMessage());
+        assertFalse(find(Notification.class).exists());
+        assertEquals(rows, rowCount());
+    }
+
+    @Test
+    void whitespaceOnlyNameAndMessageAreBlank() {
+        navigate(ContactView.class);
+        fill("   ", "", "0401 234 567", "  ");
+
+        test(sendButton()).click();
+
+        assertEquals("Name is required", nameField().getErrorMessage());
+        assertEquals("Message is required", messageField().getErrorMessage());
+        assertFalse(find(Notification.class).exists());
+    }
+
+    @Test
+    void malformedEmailIsRejectedAndTheTypedValuesStay() {
+        navigate(ContactView.class);
+        fill("Ann", "ann@example", "", "Hello");
+
+        test(sendButton()).click();
+
+        assertTrue(emailField().isInvalid());
+        assertEquals("Enter a valid e-mail address", emailField().getErrorMessage());
+        assertFalse(nameField().isInvalid());
+        assertFalse(messageField().isInvalid());
+        assertEquals("Ann", nameField().getValue());
+        assertEquals("ann@example", emailField().getValue());
+        assertEquals("Hello", messageField().getValue());
+        assertFalse(find(Notification.class).exists());
+    }
+
+    @Test
+    void messageLongerThanTheLimitIsRejectedButExactlyTheLimitIsAccepted() {
+        navigate(ContactView.class);
+        fill("Ann", "", "0401 234 567", LONG_MESSAGE);
+        test(sendButton()).click();
+        assertEquals("Message must be at most 500 characters", messageField().getErrorMessage());
+        assertFalse(find(Notification.class).exists());
+
+        messageField().setValue("x".repeat(500));
+        test(sendButton()).click();
+        assertFalse(messageField().isInvalid());
+        assertTrue(find(Notification.class).exists());
+    }
+
+    @Test
+    void phoneNumberAloneIsEnoughAndTheMessageGoesToTheTopOfTheList() {
+        navigate(ContactView.class);
+        String name = uniqueName();
+        fill(name, "", "0401 234 567", "Call me back");
+
+        test(sendButton()).click();
+
+        assertTrue(find(Notification.class).single().getElement().getProperty("text").contains("Message sent"));
+        assertEquals(name, firstRow().name());
+        assertEquals("Call me back", firstRow().message());
+        assertEquals("", nameField().getValue());
+        assertEquals("", phoneField().getValue());
+        assertEquals("", messageField().getValue());
+        assertFalse(sendButton().isEnabled());
+    }
+
+    @Test
+    void emailAloneIsEnough() {
+        navigate(ContactView.class);
+        String name = uniqueName();
+        fill(name, "ann@example.com", "", "Hello there");
+
+        test(sendButton()).click();
+
+        assertEquals(name, firstRow().name());
+        assertEquals("ann@example.com", firstRow().email());
+        assertFalse(sendButton().isEnabled());
+    }
+
+    @Test
+    void sendButtonIsEnabledAgainAfterTheNextEdit() {
+        navigate(ContactView.class);
+        fill(uniqueName(), "", "0401 234 567", "First");
+        test(sendButton()).click();
+        assertFalse(sendButton().isEnabled());
+
+        nameField().setValue("Next");
+
+        assertTrue(sendButton().isEnabled());
+    }
+
+    @Test
+    void enterSendsTheMessage() {
+        navigate(ContactView.class);
+        String name = uniqueName();
+        fill(name, "", "0401 234 567", "Sent with Enter");
+
+        fireShortcut(Key.ENTER);
+
+        assertTrue(find(Notification.class).exists());
+        assertEquals(name, firstRow().name());
+        assertEquals("", messageField().getValue());
+    }
+
+    @Test
+    void enterOnAnInvalidFormShowsErrorsAndSendsNothing() {
+        navigate(ContactView.class);
+        int rows = rowCount();
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals("Name is required", nameField().getErrorMessage());
+        assertFalse(find(Notification.class).exists());
+        assertEquals(rows, rowCount());
+    }
+
+    @Test
+    void enterDoesNothingWhileSendIsDisabled() {
+        navigate(ContactView.class);
+        fill(uniqueName(), "", "0401 234 567", "Once");
+        test(sendButton()).click();
+        int rows = rowCount();
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals(rows, rowCount());
+        assertFalse(nameField().isInvalid());
+    }
+
+    @Test
+    void sentMessagesSurviveLeavingAndComingBack() {
+        navigate(ContactView.class);
+        String name = uniqueName();
+        fill(name, "", "0401 234 567", "Remember me");
+        test(sendButton()).click();
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        assertEquals(name, firstRow().name());
+    }
+
+    @Test
+    void aboutLinkWithTypedInputAsksBeforeLeaving() {
+        navigate(ContactView.class);
+        nameField().setValue("Ann");
+
+        test(find(RouterLink.class).single()).click();
+
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertTrue(find(Dialog.class).single().isOpened());
+        assertEquals("Ann", nameField().getValue());
+    }
+
+    @Test
+    void keepEditingClosesTheDialogAndStaysOnTheForm() {
+        navigate(ContactView.class);
+        nameField().setValue("Ann");
+        test(find(RouterLink.class).single()).click();
+
+        test(find(Button.class).withText("Keep editing").single()).click();
+
+        assertFalse(find(Dialog.class).exists());
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("Ann", nameField().getValue());
+
+        test(find(RouterLink.class).single()).click();
+
+        assertTrue(find(Dialog.class).single().isOpened());
+        assertInstanceOf(ContactView.class, getCurrentView());
+    }
+
+    @Test
+    void discardGoesToTheAboutView() {
+        navigate(ContactView.class);
+        nameField().setValue("Ann");
+        test(find(RouterLink.class).single()).click();
+
+        test(find(Button.class).withText("Discard").single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertEquals("About", find(H1.class).single().getText());
+    }
+
+    @Test
+    void leavingWithAnEmptyFormIsNotInterrupted() {
+        navigate(ContactView.class);
+
+        test(find(RouterLink.class).single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertFalse(find(Dialog.class).exists());
+    }
+
+    @Test
+    void anyOneFilledFieldCountsAsTypedInput() {
+        navigate(ContactView.class);
+        emailField().setValue("ann@example.com");
+
+        test(find(RouterLink.class).single()).click();
+
+        assertTrue(find(Dialog.class).single().isOpened());
+    }
+
+    @Test
+    void enterOnTheAboutViewDoesNotSendAnythingFromTheLeftContactView() {
+        navigate(ContactView.class);
+        int rows = rowCount();
+        fill(uniqueName(), "", "0401 234 567", "Stale");
+        test(find(RouterLink.class).single()).click();
+        test(find(Button.class).withText("Discard").single()).click();
+
+        fireShortcut(Key.ENTER);
+
+        assertFalse(find(Notification.class).exists());
+        navigate(ContactView.class);
+        assertEquals(rows, rowCount());
+    }
+
+    private String uniqueName() {
+        return "Ann " + UUID.randomUUID();
+    }
+
+    private void fill(String name, String email, String phone, String message) {
+        nameField().setValue(name);
+        emailField().setValue(email);
+        phoneField().setValue(phone);
+        messageField().setValue(message);
+    }
+
+    private TextField nameField() {
+        return find(TextField.class).withLabel("Name").single();
+    }
+
+    private TextField phoneField() {
+        return find(TextField.class).withLabel("Phone").single();
+    }
+
+    private EmailField emailField() {
+        return find(EmailField.class).withLabel("Email").single();
+    }
+
+    private TextArea messageField() {
+        return find(TextArea.class).withLabel("Message").single();
+    }
+
+    private Button sendButton() {
+        return find(Button.class).withText("Send").single();
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<ContactMessage> grid() {
+        return find(Grid.class).single();
+    }
+
+    private int rowCount() {
+        return grid().getListDataView().getItemCount();
+    }
+
+    private ContactMessage firstRow() {
+        return grid().getListDataView().getItems().findFirst().orElseThrow();
+    }
+}
